// @ts-check
import js from "@eslint/js";
import tseslint from "typescript-eslint";
import eslintConfigPrettier from "eslint-config-prettier";

export default tseslint.config(
  {
    // src/planRegister/vendored/ is generated byte-for-byte by
    // sync_shared_unit.ts's --check drift mode (RU-012, node P2-N010)
    // from the canonical copy in majodali/project-orchestrator — not
    // subject to this repository's own lint config, the same reason
    // it is excluded from Prettier (see .prettierignore).
    ignores: [
      "dist/**",
      // Lambda bundler output (package.json's `bundle:lambda`, also
      // what `sam build` produces into `.aws-sam/`) — build artifacts,
      // gitignored, not source. test/lambdaBundle.test.ts (node
      // P2-N010 rework) runs `bundle:lambda` as part of the test
      // suite, so this directory can now exist in the working tree
      // whenever lint runs after test, not just after a manual
      // `npm run bundle:lambda` — same reasoning as `dist/**` above.
      "dist-lambda/**",
      ".aws-sam/**",
      "node_modules/**",
      "coverage/**",
      "src/planRegister/vendored/**",
    ],
  },
  js.configs.recommended,
  ...tseslint.configs.recommended,
  eslintConfigPrettier,
  {
    // Plain Node scripts: the recommended rules with Node's globals.
    files: ["scripts/**/*.mjs"],
    languageOptions: {
      globals: { console: "readonly", process: "readonly" },
    },
  },
  {
    // Type-aware linting for the TypeScript sources only; a plain
    // JavaScript file such as scripts/prepare.mjs takes the recommended
    // rules without a TypeScript project.
    files: ["**/*.ts"],
    languageOptions: {
      parserOptions: {
        project: "./tsconfig.eslint.json",
        tsconfigRootDir: import.meta.dirname,
      },
    },
  },
);
